glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

uniform PROPERTIES {
  vec4 flameColor1;
    vec4 flameColor2;
      vec4 igniteUv;
      vec4 uvRect;
      float time;
  float burnProgress;
  float burnDirection;
  float noiseSeed;
  vec4 noiseSeedVec;
  float noiseScale;
  float octave2Scale;
  float octave2Weight;
  float burnVTear;
  float burnVPower;
  float noiseStrength;
  float noiseFlowX;
  float noiseFlowY;
  float radialWarp;
  float edgeWidthInner;
  float curlStrength;
  float innerGlowBoost;
  float edgeWidthOuter;
  float outerGlowBoost;
  float burnAspect;
  float maskMode;
  vec4 flameMaskRect;
  vec4 flameMaskRect2;
  vec4 flameMaskChannel;
  vec4 flameMaskChannel2;
  vec4 maskCardUvRect;
  vec4 selectBaseTintParams;
  vec4 selectBaseTintColor;
  vec4 selectBaseGlowWeights;
  vec4 selectBaseUvRect;
  float flameMaskBlend;
  float flameMaskThreshold;
  float flameMaskSoftness;
  float flameMaskGain;
  float flameMaskProgressBias;
  float flameMaskFlipY;
  float rtRimSampleRadius;
  float rtRimStrength;
  float spreadPhasePivot;
  float rtInfluenceFadeStart;
  float rtInfluenceFadeEnd;
  float entranceRtMaskProgress;
  float rtMaskLightMode;
  float rtSampleErrorSignal;
    float fireNeonDebugMode;
    float sourceFlipY;
  };

void main() {
  vec4 pos = vec4(a_position, 1.0);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  v_uv0 = a_uv0;
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
  precision highp float;

  in vec4 v_color;

  #if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
  uniform sampler2D flameMaskTex;
  #endif

  uniform PROPERTIES {
    vec4 flameColor1;
      vec4 flameColor2;
        vec4 igniteUv;
        vec4 uvRect;
        float time;
    float burnProgress;
    float burnDirection;
    float noiseSeed;
    vec4 noiseSeedVec;
    float noiseScale;
    float octave2Scale;
    float octave2Weight;
    float burnVTear;
    float burnVPower;
    float noiseStrength;
    float noiseFlowX;
    float noiseFlowY;
    float radialWarp;
    float edgeWidthInner;
    float curlStrength;
    float innerGlowBoost;
    float edgeWidthOuter;
    float outerGlowBoost;
    float burnAspect;
    float maskMode;
    vec4 flameMaskRect;
    vec4 flameMaskRect2;
    vec4 flameMaskChannel;
    vec4 flameMaskChannel2;
    vec4 maskCardUvRect;
    vec4 selectBaseTintParams;
    vec4 selectBaseTintColor;
    vec4 selectBaseGlowWeights;
    vec4 selectBaseUvRect;
    float flameMaskBlend;
    float flameMaskThreshold;
    float flameMaskSoftness;
    float flameMaskGain;
    float flameMaskProgressBias;
    float flameMaskFlipY;
    float rtRimSampleRadius;
    float rtRimStrength;
    float spreadPhasePivot;
    float rtInfluenceFadeStart;
    float rtInfluenceFadeEnd;
    float entranceRtMaskProgress;
    float rtMaskLightMode;
    float rtSampleErrorSignal;
      float fireNeonDebugMode;
      float sourceFlipY;
    };

  float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
  }

  float hashSeeded(vec2 p, vec2 seed) {
    return fract(sin(dot(p, seed)) * 43758.5453123);
  }

  float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
  }

  float noiseSeeded(vec2 p, vec2 seed) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    float a = hashSeeded(i, seed);
    float b = hashSeeded(i + vec2(1.0, 0.0), seed);
    float c = hashSeeded(i + vec2(0.0, 1.0), seed);
    float d = hashSeeded(i + vec2(1.0, 1.0), seed);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
  }

  float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 4; i++) {
      v += a * noise(p);
      p *= 2.0;
      a *= 0.5;
    }
    return v;
  }

  /**
   * 主火线噪声（两层）：n0 + n1*w2，再按 (1+w2) 归一。
   * p 调用侧已含 noiseScale / flow / seed；二阶为相对 p 的频率乘子。
   */
  float sampleBurnFieldFs(vec2 p) {
    float o2 = max(octave2Scale, 0.01);
    float w2 = max(octave2Weight, 0.0);
    float n0 = noiseSeeded(p, vec2(127.1, 311.7));
    float n1 = noiseSeeded(p * o2, vec2(269.5, 183.3));
    float wSum = max(1.0 + w2, 0.0001);
    return (n0 + n1 * w2) / wSum;
  }

  vec2 resolveFlameMaskUv(vec2 sampleLocalUv, vec4 maskRect) {
    vec2 maskRectSize = max(maskRect.zw, vec2(0.0001, 0.0001));
    vec2 maskCardRectSize = max(maskCardUvRect.zw, vec2(0.0001, 0.0001));
    vec2 maskCardUv = maskCardUvRect.xy + clamp(sampleLocalUv, 0.0, 1.0) * maskCardRectSize;
    vec2 maskUv = maskRect.xy + maskCardUv * maskRectSize;
    if (flameMaskFlipY > 0.5) {
      maskUv.y = 1.0 - maskUv.y;
    }
    return maskUv;
  }

  vec4 applyFlameMaskChannel(vec4 texel, vec4 channel) {
    float channelSum = dot(channel, vec4(1.0));
    if (channelSum > 1.5) {
      return texel;
    }
    float mask = dot(texel, channel);
    return vec4(mask, mask, mask, mask);
  }

  vec4 sampleFlameMask(vec2 sampleLocalUv) {
    vec4 texel0 = applyFlameMaskChannel(texture2D(flameMaskTex, resolveFlameMaskUv(sampleLocalUv, flameMaskRect)), flameMaskChannel);
    vec4 texel1 = applyFlameMaskChannel(texture2D(flameMaskTex, resolveFlameMaskUv(sampleLocalUv, flameMaskRect2)), flameMaskChannel2);
    return mix(texel0, texel1, clamp(flameMaskBlend, 0.0, 1.0));
  }

  float resolveRtAlpha(vec4 texel) {
    float rgbMax = max(max(texel.r, texel.g), texel.b);
    float rgbAlpha = smoothstep(0.002, 0.028, rgbMax);
    float alphaLost = 1.0 - step(0.002, texel.a);
    return max(texel.a, rgbAlpha * alphaLost);
  }

  void main() {
    vec2 localUv = clamp(v_uv0, 0.0, 1.0);
    vec2 sourceLocalUv = localUv;
    if (sourceFlipY > 0.5) {
      sourceLocalUv.y = 1.0 - sourceLocalUv.y;
    }
    vec2 uvSize = max(uvRect.zw, vec2(0.0001, 0.0001));
    vec2 sourceUv = uvRect.xy + sourceLocalUv * uvSize;
    vec4 texel = texture2D(texture, sourceUv);
    if (fireNeonDebugMode >= 1.5) {
      gl_FragColor = vec4(1.0, 0.0, 1.0, 0.85);
      return;
    }
    vec4 base = texel * v_color;
    base.a = max(base.a, resolveRtAlpha(texel) * v_color.a);
    if (selectBaseTintParams.x > 0.5 && base.a > 0.0001) {
      vec2 rectMin = selectBaseUvRect.xy;
      vec2 rectMax = selectBaseUvRect.xy + max(selectBaseUvRect.zw, vec2(0.0, 0.0));
      float inRect = step(rectMin.x, localUv.x) * step(localUv.x, rectMax.x) * step(rectMin.y, localUv.y) * step(localUv.y, rectMax.y);
      float amount = clamp(selectBaseTintParams.y, 0.0, 1.0) * inRect;
      if (amount > 0.0001) {
        float a = max(base.a, 0.0001);
        vec3 baseRgb = base.rgb / a;
        vec3 glow = max(selectBaseTintColor.rgb, vec3(0.0));
        float mulW = selectBaseTintParams.z;
        float softW = selectBaseTintParams.w;
        float scrW = selectBaseGlowWeights.x;
        if (mulW <= 0.0 && softW <= 0.0 && scrW <= 0.0) {
          mulW = 1.2;
          softW = 0.4;
          scrW = 0.25;
        }

        vec3 lit = baseRgb * (1.0 + glow * (amount * mulW));
        lit += glow * clamp(a, 0.0, 1.0) * (amount * softW);
        vec3 screened = lit + glow - lit * glow;
        lit = mix(lit, screened, clamp(amount * scrW, 0.0, 1.0));
        base.rgb = lit * a;
      }
    }
    if (base.a <= 0.001) {
      if (rtSampleErrorSignal >= 0.5) {
        float checker = mod(floor(localUv.x * 12.0) + floor(localUv.y * 20.0), 2.0);
        vec3 errColor = mix(vec3(1.0, 0.0, 1.0), vec3(1.0, 0.85, 0.0), checker);
        gl_FragColor = vec4(errColor, 0.88);
        return;
      }
      discard;
    }
      if (fireNeonDebugMode >= 0.5) {
        gl_FragColor = base;
        return;
      }
        vec2 center = clamp(igniteUv.xy, 0.0, 1.0);
    float aspect = max(0.0001, burnAspect);
    vec2 metricScale = vec2(aspect, 1.0);
    vec2 metricToCenter = (localUv - center) * metricScale;

    float vTear = max(burnVTear, 0.01);
    float vPower = clamp(burnVPower, 1.0, 3.0);
    float openPosY = step(center.y, 0.5);

    float dy0 = localUv.y - center.y;
    float up0 = mix(max(-dy0, 0.0), max(dy0, 0.0), openPosY);
    float down0 = mix(max(dy0, 0.0), max(-dy0, 0.0), openPosY);
    float lat0 = abs((localUv.x - center.x) * aspect);
    float raw0 = up0 + down0 * 1.12 + vTear * pow(lat0 + 1e-6, vPower);

    float upA = mix(max(center.y - 0.0, 0.0), max(0.0 - center.y, 0.0), openPosY);
    float downA = mix(max(0.0 - center.y, 0.0), max(center.y - 0.0, 0.0), openPosY);
    float upB = mix(max(center.y - 1.0, 0.0), max(1.0 - center.y, 0.0), openPosY);
    float downB = mix(max(1.0 - center.y, 0.0), max(center.y - 1.0, 0.0), openPosY);
    float latL = abs((0.0 - center.x) * aspect);
    float latR = abs((1.0 - center.x) * aspect);
    float maxDist = max(
      max(upA + downA * 1.12 + vTear * pow(latL + 1e-6, vPower),
          upA + downA * 1.12 + vTear * pow(latR + 1e-6, vPower)),
      max(upB + downB * 1.12 + vTear * pow(latL + 1e-6, vPower),
          upB + downB * 1.12 + vTear * pow(latR + 1e-6, vPower))
    );
    float dist = raw0 / max(maxDist, 0.0001);
    vec2 metricUv = localUv * metricScale;
    vec2 seedOffset = noiseSeedVec.xy;
    float p = max(burnProgress, 0.0);
    float overburn = max(noiseSeedVec.z, 0.0);
    float completeP = 1.0 + overburn;
    float overT = overburn > 0.0001 ? smoothstep(1.0, completeP, p) : step(1.0, p);
    float dir = step(0.5, burnDirection);
    float maskModeOn = step(0.5, maskMode);
    if (maskModeOn < 0.5 && dir < 0.5 && p <= 0.0001) {
      vec4 initialColor = base;
      gl_FragColor = initialColor;
      return;
    }
    if (maskModeOn < 0.5 && dir < 0.5 && p >= completeP - 0.0001) {
      discard;
    }
    if (maskModeOn < 0.5 && dir >= 0.5 && p <= 0.0001) {
      discard;
    }
    if (maskModeOn < 0.5 && dir >= 0.5 && p >= completeP - 0.0001) {
      vec4 finalColor = base;
      gl_FragColor = finalColor;
      return;
    }

    float innerW = max(edgeWidthInner, 0.0001);
    float outerW = max(edgeWidthOuter, 0.0001);

    if (maskModeOn < 0.5) {

      float startRamp = 0.03;
      float noiseGate = smoothstep(0.0, startRamp, p);
      float noiseAmpScale = noiseGate * (1.0 - overT);
      float maxNoiseAmp = (0.5 * abs(noiseStrength) + 0.5 * abs(radialWarp)) * noiseAmpScale;
      float burnValueBase = mix(dist - p, p - dist, dir);
      float bandLimit = max(innerW, outerW);
      if (burnValueBase - maxNoiseAmp >= bandLimit) {
        gl_FragColor = base;
        return;
      }
      if (burnValueBase + maxNoiseAmp < 0.0) {
        discard;
      }

      float n = sampleBurnFieldFs(metricUv * noiseScale + vec2(time * noiseFlowX, time * noiseFlowY) + seedOffset);
      float radialNoise = sampleBurnFieldFs(metricToCenter * 8.0 + vec2(5.3 + time * noiseFlowX * 0.1, 1.9 + time * noiseFlowY * 0.1) + seedOffset);
      float noiseTerm = ((n - 0.5) * noiseStrength + (radialNoise - 0.5) * radialWarp) * noiseAmpScale;
      float burnValue = burnValueBase + noiseTerm;
      if (burnValue < 0.0) {
        discard;
      }
      if (burnValue >= bandLimit) {
        gl_FragColor = base;
        return;
      }
      float innerBand = 1.0 - smoothstep(0.0, innerW, burnValue);
      float outerBand = 1.0 - smoothstep(0.0, outerW, burnValue);

      vec4 outColor = base;
      vec3 outerEmission = flameColor2.rgb * outerGlowBoost * 2.0;
      vec3 innerEmission = flameColor1.rgb * innerGlowBoost * 5.0;
      vec3 burnColor = mix(outerEmission, innerEmission, innerBand);
      vec3 emission = outerEmission * (outerBand * 0.6) + innerEmission * (innerBand * 0.85);
      vec3 baseRgb = base.rgb;
      if (base.a > 0.0001) {
        baseRgb = base.rgb / base.a;
      }
      vec3 mixedRgb = mix(baseRgb, burnColor, outerBand * 0.85);
      mixedRgb += emission * (0.28 + 0.35 * outerBand);
      float finalAlpha = base.a;
      outColor.rgb = mixedRgb * finalAlpha;
      outColor.a = finalAlpha;

      if (outColor.a <= 0.001) {
        discard;
      }

      gl_FragColor = outColor;
      return;
    }

    float innerBand = 0.0;
    float outerBand = 0.0;
    float burnValue = 0.0;
    float cleanBlend = 0.0;
    float cleanAlpha = 0.0;
    float rtStyleRim = 0.0;
    float rtStyleCore = 0.0;
    float rtProgress = entranceRtMaskProgress >= 0.0 ? clamp(entranceRtMaskProgress, 0.0, 1.0) : p;
    float rtFadeStart = clamp(rtInfluenceFadeStart, 0.0, 1.0);
    float rtFadeEnd = clamp(max(rtFadeStart + 0.0001, rtInfluenceFadeEnd), 0.0, 1.0);
    float rtRelease = smoothstep(rtFadeStart, rtFadeEnd, rtProgress);

    vec4 maskTexel = sampleFlameMask(localUv);
    float maskRaw = max(maskTexel.a, maskTexel.r);
    float gain = max(0.01, flameMaskGain);
    float threshold = clamp(flameMaskThreshold, 0.0, 1.0);
    float soft = max(0.0001, flameMaskSoftness);
    float progressBias = clamp(flameMaskProgressBias, 0.0, 1.0);
    float pivot = clamp(spreadPhasePivot, 0.0, 0.98);

    float rtRimStep = max(0.0005, rtRimSampleRadius);
    vec2 uvL = clamp(localUv - vec2(rtRimStep, 0.0), 0.0, 1.0);
    vec2 uvR = clamp(localUv + vec2(rtRimStep, 0.0), 0.0, 1.0);
    vec2 uvB = clamp(localUv - vec2(0.0, rtRimStep), 0.0, 1.0);
    vec2 uvT = clamp(localUv + vec2(0.0, rtRimStep), 0.0, 1.0);
    float aL = sampleFlameMask(uvL).a;
    float aR = sampleFlameMask(uvR).a;
    float aB = sampleFlameMask(uvB).a;
    float aT = sampleFlameMask(uvT).a;
    float neighborMin = min(min(aL, aR), min(aB, aT));
    rtStyleRim = smoothstep(0.01, 0.28, max(0.0, maskTexel.a - neighborMin));
    rtStyleCore = smoothstep(0.65, 0.98, maskRaw);

    float phaseP = clamp(rtProgress / max(0.0001, pivot), 0.0, 1.0);
    float phaseBias = max(0.55, progressBias);
    float phaseCurve = pow(phaseP, 0.72);
    float dynamicThreshold = clamp(mix(1.0 - phaseBias, threshold, phaseCurve), 0.0, 1.0);
    float maskValue = smoothstep(dynamicThreshold - soft, dynamicThreshold + soft, maskRaw * gain);
    float phaseConverge = smoothstep(0.90, 1.0, rtRelease);
    maskValue = max(maskValue, phaseConverge * 0.995);
    float seedThreshold = clamp(mix(1.0 - phaseBias, threshold, 1.0), 0.0, 1.0);
    float seedMask = smoothstep(seedThreshold - soft, seedThreshold + soft, maskRaw * gain);

    float directInnerBand = smoothstep(0.25, 0.92, maskValue);
    float directOuterBand = maskValue;
    float directBurnValue = 1.0 - maskValue;
    float directCleanAlpha = maskValue;
    innerBand = directInnerBand;
    outerBand = directOuterBand;
    burnValue = directBurnValue;
    cleanAlpha = directCleanAlpha;

    float phaseBlendWidth = max(0.08, min(0.18, (1.0 - pivot) * 0.25));
    float phaseBlend = smoothstep(pivot, min(1.0, pivot + phaseBlendWidth), rtProgress);
    if (phaseBlend > 0.0001 && rtMaskLightMode < 0.5) {
      float tSpread = clamp((rtProgress - pivot) / max(0.0001, 1.0 - pivot), 0.0, 1.0);
      float spreadPow = 1.15;
      float radiusMax = mix(0.18, 0.30, clamp(1.0 - pivot, 0.0, 1.0));
      float spreadNoise = fbm(metricUv * 7.0 + vec2(time * noiseFlowX * 0.25, time * noiseFlowY * 0.25) + seedOffset);
      float spreadNoise2 = fbm(metricUv * 11.0 + vec2(13.7 + time * noiseFlowY * 0.2, 8.9 + time * noiseFlowX * 0.2) + seedOffset);
      float spreadNoiseMul = 0.82 + spreadNoise * 0.36;
      float radius = radiusMax * pow(tSpread, spreadPow) * spreadNoiseMul;
      float prevRadius = max(0.0, radius - max(0.0005, radius * 0.08));

      float gradStep = 0.02;
      vec2 uvL2 = clamp(localUv - vec2(gradStep, 0.0), 0.0, 1.0);
      vec2 uvR2 = clamp(localUv + vec2(gradStep, 0.0), 0.0, 1.0);
      vec2 uvB2 = clamp(localUv - vec2(0.0, gradStep), 0.0, 1.0);
      vec2 uvT2 = clamp(localUv + vec2(0.0, gradStep), 0.0, 1.0);
      vec4 gradTexelL = sampleFlameMask(uvL2);
      vec4 gradTexelR = sampleFlameMask(uvR2);
      vec4 gradTexelB = sampleFlameMask(uvB2);
      vec4 gradTexelT = sampleFlameMask(uvT2);
      float gradL = max(gradTexelL.a, gradTexelL.r);
      float gradR = max(gradTexelR.a, gradTexelR.r);
      float gradB = max(gradTexelB.a, gradTexelB.r);
      float gradT = max(gradTexelT.a, gradTexelT.r);
      vec2 gradVec = vec2(gradR - gradL, gradT - gradB);
      vec2 noiseVec = vec2(spreadNoise - 0.5, spreadNoise2 - 0.5);
      float flowEnergy = clamp(length(gradVec) * 8.0, 0.0, 1.0);
      vec2 flowDir = normalize(gradVec + noiseVec * (0.55 + 0.25 * (1.0 - flowEnergy)) + vec2(0.0001, 0.0002));
      vec2 flowTan = vec2(-flowDir.y, flowDir.x);
      float advect = (0.12 + 0.28 * tSpread) * (0.65 + 0.35 * flowEnergy);
      float swirl = (spreadNoise2 - 0.5) * (0.10 + 0.16 * tSpread);

      vec2 metricDirX = normalize(vec2(1.0 / max(metricScale.x, 0.0001), 0.0));
      vec2 metricDirY = normalize(vec2(0.0, 1.0 / max(metricScale.y, 0.0001)));
      vec2 metricDiag1 = normalize(metricDirX + metricDirY);
      vec2 metricDiag2 = normalize(metricDirX - metricDirY);
      vec2 dirX = normalize(metricDirX + flowDir * advect + flowTan * swirl + vec2(0.0001));
      vec2 dirY = normalize(metricDirY + flowDir * (advect * 0.82) - flowTan * (swirl * 0.9) + vec2(0.0001));
      vec2 dirD1 = normalize(metricDiag1 + flowDir * (advect * 0.7) + flowTan * (swirl * 0.6) + vec2(0.0001));
      vec2 dirD2 = normalize(metricDiag2 + flowDir * (advect * 0.7) - flowTan * (swirl * 0.6) + vec2(0.0001));

      vec2 rX = dirX * radius;
      vec2 rY = dirY * radius;
      vec2 rD1 = dirD1 * radius;
      vec2 rD2 = dirD2 * radius;
      vec2 rXm = dirX * prevRadius;
      vec2 rYm = dirY * prevRadius;
      vec2 rD1m = dirD1 * prevRadius;
      vec2 rD2m = dirD2 * prevRadius;

      vec2 uvS;
      vec4 texel;
      float grownMask = seedMask;
      float prevMask = seedMask;
      float sampled = 0.0;

      uvS = clamp(localUv + rX, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv - rX, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv + rY, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv - rY, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv + rD1, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv - rD1, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv + rD2, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv - rD2, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);

      uvS = clamp(localUv + rXm, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv - rXm, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv + rYm, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv - rYm, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv + rD1m, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv - rD1m, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv + rD2m, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv - rD2m, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);

      float targetMask = smoothstep(0.001, 0.25, base.a);
      grownMask *= targetMask;
      prevMask *= targetMask;
      float frontier = max(0.0, grownMask - prevMask);

      float settle = smoothstep(0.55, 1.0, tSpread);
      float grownInnerBand = clamp(frontier * (1.2 - settle * 0.35), 0.0, 1.0);
      float grownOuterBand = clamp(grownMask * (1.0 - settle * 0.2), 0.0, 1.0);
      innerBand = mix(directInnerBand, grownInnerBand, phaseBlend);
      outerBand = mix(directOuterBand, grownOuterBand, phaseBlend);
      burnValue = mix(directBurnValue, 1.0 - grownMask, phaseBlend);
      cleanBlend = settle * phaseBlend;
      cleanAlpha = mix(directCleanAlpha, grownMask, phaseBlend);
    }

    vec4 outColor = base;

    vec3 outerEmission = flameColor2.rgb * outerGlowBoost * 2.0;
    vec3 innerEmission = flameColor1.rgb * innerGlowBoost * 5.0;
    vec3 burnColor = mix(outerEmission, innerEmission, clamp(innerBand, 0.0, 1.0));
    vec3 emission = outerEmission * (outerBand * 0.6) + innerEmission * (innerBand * 0.85);
    vec3 baseRgb = base.rgb;
    if (base.a > 0.0001) {
      baseRgb = base.rgb / base.a;
    }
    vec3 mixedRgb = mix(baseRgb, burnColor, outerBand * 0.85);
    mixedRgb += emission * (0.28 + 0.35 * outerBand);
    vec3 finalRgb = mixedRgb;
    float finalAlpha = base.a;
    vec3 rtCore = vec3(1.0);
    vec3 rtOuter = mix(flameColor2.rgb, vec3(1.0), 0.22);
    vec3 rtLayered = vec3(0.0);
    rtLayered += rtOuter * (0.40 + 0.60 * outerBand);
    rtLayered += rtCore * (0.45 * innerBand + 0.30 * rtStyleCore);
    rtLayered += flameColor2.rgb * (0.25 + 0.55 * rtStyleRim) * outerBand;
    vec3 rtFlameTint = clamp(rtLayered, 0.0, 1.0);
    finalRgb = mix(rtFlameTint, baseRgb, rtRelease);
    float maskedAlpha = base.a * clamp(cleanAlpha, 0.0, 1.0);
    finalAlpha = mix(maskedAlpha, base.a, rtRelease);
    float alphaProgress = entranceRtMaskProgress >= 0.0 ? clamp(entranceRtMaskProgress, 0.0, 1.0) : p;
    finalAlpha *= smoothstep(0.015, 0.08, alphaProgress);
    outColor.rgb = finalRgb;
    outColor.a = finalAlpha;

    if (outColor.a <= 0.001) {
      discard;
    }

  gl_FragColor = outColor;
}

glsl1.vert:
precision highp float;
uniform mat4 cc_matViewProj;
uniform mat4 cc_matWorld;

attribute vec3 a_position;
attribute vec4 a_color;
varying vec4 v_color;

#if USE_TEXTURE
attribute vec2 a_uv0;
varying vec2 v_uv0;
#endif

void main() {
  vec4 pos = vec4(a_position, 1.0);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  v_uv0 = a_uv0;
  v_color = a_color;
  gl_Position = pos;
}

glsl1.frag:
  precision highp float;

  varying vec4 v_color;

  #if USE_TEXTURE
  varying vec2 v_uv0;
  uniform sampler2D texture;
  uniform sampler2D flameMaskTex;
  #endif

  uniform vec4 flameColor1;
uniform vec4 flameColor2;
uniform vec4 igniteUv;
uniform vec4 uvRect;
uniform float time;
uniform float burnProgress;
uniform float burnDirection;
uniform vec4 noiseSeedVec;
uniform float noiseScale;
uniform float octave2Scale;
uniform float octave2Weight;
uniform float burnVTear;
uniform float burnVPower;
uniform float noiseStrength;
uniform float noiseFlowX;
uniform float noiseFlowY;
uniform float radialWarp;
uniform float edgeWidthInner;
uniform float innerGlowBoost;
uniform float edgeWidthOuter;
uniform float outerGlowBoost;
uniform float burnAspect;
uniform float maskMode;
uniform vec4 flameMaskRect;
uniform vec4 flameMaskRect2;
uniform vec4 flameMaskChannel;
uniform vec4 flameMaskChannel2;
uniform vec4 maskCardUvRect;
uniform vec4 selectBaseTintParams;
uniform vec4 selectBaseTintColor;
uniform vec4 selectBaseGlowWeights;
uniform vec4 selectBaseUvRect;
uniform float flameMaskBlend;
uniform float flameMaskThreshold;
uniform float flameMaskSoftness;
uniform float flameMaskGain;
uniform float flameMaskProgressBias;
uniform float flameMaskFlipY;
uniform float rtRimSampleRadius;
uniform float spreadPhasePivot;
uniform float rtInfluenceFadeStart;
uniform float rtInfluenceFadeEnd;
uniform float entranceRtMaskProgress;
uniform float rtMaskLightMode;
uniform float rtSampleErrorSignal;
uniform float fireNeonDebugMode;
uniform float sourceFlipY;

  float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
  }

  float hashSeeded(vec2 p, vec2 seed) {
    return fract(sin(dot(p, seed)) * 43758.5453123);
  }

  float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
  }

  float noiseSeeded(vec2 p, vec2 seed) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    float a = hashSeeded(i, seed);
    float b = hashSeeded(i + vec2(1.0, 0.0), seed);
    float c = hashSeeded(i + vec2(0.0, 1.0), seed);
    float d = hashSeeded(i + vec2(1.0, 1.0), seed);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
  }

  float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 4; i++) {
      v += a * noise(p);
      p *= 2.0;
      a *= 0.5;
    }
    return v;
  }

  /**
   * 主火线噪声（两层）：n0 + n1*w2，再按 (1+w2) 归一。
   * p 调用侧已含 noiseScale / flow / seed；二阶为相对 p 的频率乘子。
   */
  float sampleBurnFieldFs(vec2 p) {
    float o2 = max(octave2Scale, 0.01);
    float w2 = max(octave2Weight, 0.0);
    float n0 = noiseSeeded(p, vec2(127.1, 311.7));
    float n1 = noiseSeeded(p * o2, vec2(269.5, 183.3));
    float wSum = max(1.0 + w2, 0.0001);
    return (n0 + n1 * w2) / wSum;
  }

  vec2 resolveFlameMaskUv(vec2 sampleLocalUv, vec4 maskRect) {
    vec2 maskRectSize = max(maskRect.zw, vec2(0.0001, 0.0001));
    vec2 maskCardRectSize = max(maskCardUvRect.zw, vec2(0.0001, 0.0001));
    vec2 maskCardUv = maskCardUvRect.xy + clamp(sampleLocalUv, 0.0, 1.0) * maskCardRectSize;
    vec2 maskUv = maskRect.xy + maskCardUv * maskRectSize;
    if (flameMaskFlipY > 0.5) {
      maskUv.y = 1.0 - maskUv.y;
    }
    return maskUv;
  }

  vec4 applyFlameMaskChannel(vec4 texel, vec4 channel) {
    float channelSum = dot(channel, vec4(1.0));
    if (channelSum > 1.5) {
      return texel;
    }
    float mask = dot(texel, channel);
    return vec4(mask, mask, mask, mask);
  }

  vec4 sampleFlameMask(vec2 sampleLocalUv) {
    vec4 texel0 = applyFlameMaskChannel(texture2D(flameMaskTex, resolveFlameMaskUv(sampleLocalUv, flameMaskRect)), flameMaskChannel);
    vec4 texel1 = applyFlameMaskChannel(texture2D(flameMaskTex, resolveFlameMaskUv(sampleLocalUv, flameMaskRect2)), flameMaskChannel2);
    return mix(texel0, texel1, clamp(flameMaskBlend, 0.0, 1.0));
  }

  float resolveRtAlpha(vec4 texel) {
    float rgbMax = max(max(texel.r, texel.g), texel.b);
    float rgbAlpha = smoothstep(0.002, 0.028, rgbMax);
    float alphaLost = 1.0 - step(0.002, texel.a);
    return max(texel.a, rgbAlpha * alphaLost);
  }

  void main() {
    vec2 localUv = clamp(v_uv0, 0.0, 1.0);
    vec2 sourceLocalUv = localUv;
    if (sourceFlipY > 0.5) {
      sourceLocalUv.y = 1.0 - sourceLocalUv.y;
    }
    vec2 uvSize = max(uvRect.zw, vec2(0.0001, 0.0001));
    vec2 sourceUv = uvRect.xy + sourceLocalUv * uvSize;
    vec4 texel = texture2D(texture, sourceUv);
    if (fireNeonDebugMode >= 1.5) {
      gl_FragColor = vec4(1.0, 0.0, 1.0, 0.85);
      return;
    }
    vec4 base = texel * v_color;
    base.a = max(base.a, resolveRtAlpha(texel) * v_color.a);
    if (selectBaseTintParams.x > 0.5 && base.a > 0.0001) {
      vec2 rectMin = selectBaseUvRect.xy;
      vec2 rectMax = selectBaseUvRect.xy + max(selectBaseUvRect.zw, vec2(0.0, 0.0));
      float inRect = step(rectMin.x, localUv.x) * step(localUv.x, rectMax.x) * step(rectMin.y, localUv.y) * step(localUv.y, rectMax.y);
      float amount = clamp(selectBaseTintParams.y, 0.0, 1.0) * inRect;
      if (amount > 0.0001) {
        float a = max(base.a, 0.0001);
        vec3 baseRgb = base.rgb / a;
        vec3 glow = max(selectBaseTintColor.rgb, vec3(0.0));
        float mulW = selectBaseTintParams.z;
        float softW = selectBaseTintParams.w;
        float scrW = selectBaseGlowWeights.x;
        if (mulW <= 0.0 && softW <= 0.0 && scrW <= 0.0) {
          mulW = 1.2;
          softW = 0.4;
          scrW = 0.25;
        }

        vec3 lit = baseRgb * (1.0 + glow * (amount * mulW));
        lit += glow * clamp(a, 0.0, 1.0) * (amount * softW);
        vec3 screened = lit + glow - lit * glow;
        lit = mix(lit, screened, clamp(amount * scrW, 0.0, 1.0));
        base.rgb = lit * a;
      }
    }
    if (base.a <= 0.001) {
      if (rtSampleErrorSignal >= 0.5) {
        float checker = mod(floor(localUv.x * 12.0) + floor(localUv.y * 20.0), 2.0);
        vec3 errColor = mix(vec3(1.0, 0.0, 1.0), vec3(1.0, 0.85, 0.0), checker);
        gl_FragColor = vec4(errColor, 0.88);
        return;
      }
      discard;
    }
      if (fireNeonDebugMode >= 0.5) {
        gl_FragColor = base;
        return;
      }
        vec2 center = clamp(igniteUv.xy, 0.0, 1.0);
    float aspect = max(0.0001, burnAspect);
    vec2 metricScale = vec2(aspect, 1.0);
    vec2 metricToCenter = (localUv - center) * metricScale;

    float vTear = max(burnVTear, 0.01);
    float vPower = clamp(burnVPower, 1.0, 3.0);
    float openPosY = step(center.y, 0.5);

    float dy0 = localUv.y - center.y;
    float up0 = mix(max(-dy0, 0.0), max(dy0, 0.0), openPosY);
    float down0 = mix(max(dy0, 0.0), max(-dy0, 0.0), openPosY);
    float lat0 = abs((localUv.x - center.x) * aspect);
    float raw0 = up0 + down0 * 1.12 + vTear * pow(lat0 + 1e-6, vPower);

    float upA = mix(max(center.y - 0.0, 0.0), max(0.0 - center.y, 0.0), openPosY);
    float downA = mix(max(0.0 - center.y, 0.0), max(center.y - 0.0, 0.0), openPosY);
    float upB = mix(max(center.y - 1.0, 0.0), max(1.0 - center.y, 0.0), openPosY);
    float downB = mix(max(1.0 - center.y, 0.0), max(center.y - 1.0, 0.0), openPosY);
    float latL = abs((0.0 - center.x) * aspect);
    float latR = abs((1.0 - center.x) * aspect);
    float maxDist = max(
      max(upA + downA * 1.12 + vTear * pow(latL + 1e-6, vPower),
          upA + downA * 1.12 + vTear * pow(latR + 1e-6, vPower)),
      max(upB + downB * 1.12 + vTear * pow(latL + 1e-6, vPower),
          upB + downB * 1.12 + vTear * pow(latR + 1e-6, vPower))
    );
    float dist = raw0 / max(maxDist, 0.0001);
    vec2 metricUv = localUv * metricScale;
    vec2 seedOffset = noiseSeedVec.xy;
    float p = max(burnProgress, 0.0);
    float overburn = max(noiseSeedVec.z, 0.0);
    float completeP = 1.0 + overburn;
    float overT = overburn > 0.0001 ? smoothstep(1.0, completeP, p) : step(1.0, p);
    float dir = step(0.5, burnDirection);
    float maskModeOn = step(0.5, maskMode);
    if (maskModeOn < 0.5 && dir < 0.5 && p <= 0.0001) {
      vec4 initialColor = base;
      gl_FragColor = initialColor;
      return;
    }
    if (maskModeOn < 0.5 && dir < 0.5 && p >= completeP - 0.0001) {
      discard;
    }
    if (maskModeOn < 0.5 && dir >= 0.5 && p <= 0.0001) {
      discard;
    }
    if (maskModeOn < 0.5 && dir >= 0.5 && p >= completeP - 0.0001) {
      vec4 finalColor = base;
      gl_FragColor = finalColor;
      return;
    }

    float innerW = max(edgeWidthInner, 0.0001);
    float outerW = max(edgeWidthOuter, 0.0001);

    if (maskModeOn < 0.5) {

      float startRamp = 0.03;
      float noiseGate = smoothstep(0.0, startRamp, p);
      float noiseAmpScale = noiseGate * (1.0 - overT);
      float maxNoiseAmp = (0.5 * abs(noiseStrength) + 0.5 * abs(radialWarp)) * noiseAmpScale;
      float burnValueBase = mix(dist - p, p - dist, dir);
      float bandLimit = max(innerW, outerW);
      if (burnValueBase - maxNoiseAmp >= bandLimit) {
        gl_FragColor = base;
        return;
      }
      if (burnValueBase + maxNoiseAmp < 0.0) {
        discard;
      }

      float n = sampleBurnFieldFs(metricUv * noiseScale + vec2(time * noiseFlowX, time * noiseFlowY) + seedOffset);
      float radialNoise = sampleBurnFieldFs(metricToCenter * 8.0 + vec2(5.3 + time * noiseFlowX * 0.1, 1.9 + time * noiseFlowY * 0.1) + seedOffset);
      float noiseTerm = ((n - 0.5) * noiseStrength + (radialNoise - 0.5) * radialWarp) * noiseAmpScale;
      float burnValue = burnValueBase + noiseTerm;
      if (burnValue < 0.0) {
        discard;
      }
      if (burnValue >= bandLimit) {
        gl_FragColor = base;
        return;
      }
      float innerBand = 1.0 - smoothstep(0.0, innerW, burnValue);
      float outerBand = 1.0 - smoothstep(0.0, outerW, burnValue);

      vec4 outColor = base;
      vec3 outerEmission = flameColor2.rgb * outerGlowBoost * 2.0;
      vec3 innerEmission = flameColor1.rgb * innerGlowBoost * 5.0;
      vec3 burnColor = mix(outerEmission, innerEmission, innerBand);
      vec3 emission = outerEmission * (outerBand * 0.6) + innerEmission * (innerBand * 0.85);
      vec3 baseRgb = base.rgb;
      if (base.a > 0.0001) {
        baseRgb = base.rgb / base.a;
      }
      vec3 mixedRgb = mix(baseRgb, burnColor, outerBand * 0.85);
      mixedRgb += emission * (0.28 + 0.35 * outerBand);
      float finalAlpha = base.a;
      outColor.rgb = mixedRgb * finalAlpha;
      outColor.a = finalAlpha;

      if (outColor.a <= 0.001) {
        discard;
      }

      gl_FragColor = outColor;
      return;
    }

    float innerBand = 0.0;
    float outerBand = 0.0;
    float burnValue = 0.0;
    float cleanBlend = 0.0;
    float cleanAlpha = 0.0;
    float rtStyleRim = 0.0;
    float rtStyleCore = 0.0;
    float rtProgress = entranceRtMaskProgress >= 0.0 ? clamp(entranceRtMaskProgress, 0.0, 1.0) : p;
    float rtFadeStart = clamp(rtInfluenceFadeStart, 0.0, 1.0);
    float rtFadeEnd = clamp(max(rtFadeStart + 0.0001, rtInfluenceFadeEnd), 0.0, 1.0);
    float rtRelease = smoothstep(rtFadeStart, rtFadeEnd, rtProgress);

    vec4 maskTexel = sampleFlameMask(localUv);
    float maskRaw = max(maskTexel.a, maskTexel.r);
    float gain = max(0.01, flameMaskGain);
    float threshold = clamp(flameMaskThreshold, 0.0, 1.0);
    float soft = max(0.0001, flameMaskSoftness);
    float progressBias = clamp(flameMaskProgressBias, 0.0, 1.0);
    float pivot = clamp(spreadPhasePivot, 0.0, 0.98);

    float rtRimStep = max(0.0005, rtRimSampleRadius);
    vec2 uvL = clamp(localUv - vec2(rtRimStep, 0.0), 0.0, 1.0);
    vec2 uvR = clamp(localUv + vec2(rtRimStep, 0.0), 0.0, 1.0);
    vec2 uvB = clamp(localUv - vec2(0.0, rtRimStep), 0.0, 1.0);
    vec2 uvT = clamp(localUv + vec2(0.0, rtRimStep), 0.0, 1.0);
    float aL = sampleFlameMask(uvL).a;
    float aR = sampleFlameMask(uvR).a;
    float aB = sampleFlameMask(uvB).a;
    float aT = sampleFlameMask(uvT).a;
    float neighborMin = min(min(aL, aR), min(aB, aT));
    rtStyleRim = smoothstep(0.01, 0.28, max(0.0, maskTexel.a - neighborMin));
    rtStyleCore = smoothstep(0.65, 0.98, maskRaw);

    float phaseP = clamp(rtProgress / max(0.0001, pivot), 0.0, 1.0);
    float phaseBias = max(0.55, progressBias);
    float phaseCurve = pow(phaseP, 0.72);
    float dynamicThreshold = clamp(mix(1.0 - phaseBias, threshold, phaseCurve), 0.0, 1.0);
    float maskValue = smoothstep(dynamicThreshold - soft, dynamicThreshold + soft, maskRaw * gain);
    float phaseConverge = smoothstep(0.90, 1.0, rtRelease);
    maskValue = max(maskValue, phaseConverge * 0.995);
    float seedThreshold = clamp(mix(1.0 - phaseBias, threshold, 1.0), 0.0, 1.0);
    float seedMask = smoothstep(seedThreshold - soft, seedThreshold + soft, maskRaw * gain);

    float directInnerBand = smoothstep(0.25, 0.92, maskValue);
    float directOuterBand = maskValue;
    float directBurnValue = 1.0 - maskValue;
    float directCleanAlpha = maskValue;
    innerBand = directInnerBand;
    outerBand = directOuterBand;
    burnValue = directBurnValue;
    cleanAlpha = directCleanAlpha;

    float phaseBlendWidth = max(0.08, min(0.18, (1.0 - pivot) * 0.25));
    float phaseBlend = smoothstep(pivot, min(1.0, pivot + phaseBlendWidth), rtProgress);
    if (phaseBlend > 0.0001 && rtMaskLightMode < 0.5) {
      float tSpread = clamp((rtProgress - pivot) / max(0.0001, 1.0 - pivot), 0.0, 1.0);
      float spreadPow = 1.15;
      float radiusMax = mix(0.18, 0.30, clamp(1.0 - pivot, 0.0, 1.0));
      float spreadNoise = fbm(metricUv * 7.0 + vec2(time * noiseFlowX * 0.25, time * noiseFlowY * 0.25) + seedOffset);
      float spreadNoise2 = fbm(metricUv * 11.0 + vec2(13.7 + time * noiseFlowY * 0.2, 8.9 + time * noiseFlowX * 0.2) + seedOffset);
      float spreadNoiseMul = 0.82 + spreadNoise * 0.36;
      float radius = radiusMax * pow(tSpread, spreadPow) * spreadNoiseMul;
      float prevRadius = max(0.0, radius - max(0.0005, radius * 0.08));

      float gradStep = 0.02;
      vec2 uvL2 = clamp(localUv - vec2(gradStep, 0.0), 0.0, 1.0);
      vec2 uvR2 = clamp(localUv + vec2(gradStep, 0.0), 0.0, 1.0);
      vec2 uvB2 = clamp(localUv - vec2(0.0, gradStep), 0.0, 1.0);
      vec2 uvT2 = clamp(localUv + vec2(0.0, gradStep), 0.0, 1.0);
      vec4 gradTexelL = sampleFlameMask(uvL2);
      vec4 gradTexelR = sampleFlameMask(uvR2);
      vec4 gradTexelB = sampleFlameMask(uvB2);
      vec4 gradTexelT = sampleFlameMask(uvT2);
      float gradL = max(gradTexelL.a, gradTexelL.r);
      float gradR = max(gradTexelR.a, gradTexelR.r);
      float gradB = max(gradTexelB.a, gradTexelB.r);
      float gradT = max(gradTexelT.a, gradTexelT.r);
      vec2 gradVec = vec2(gradR - gradL, gradT - gradB);
      vec2 noiseVec = vec2(spreadNoise - 0.5, spreadNoise2 - 0.5);
      float flowEnergy = clamp(length(gradVec) * 8.0, 0.0, 1.0);
      vec2 flowDir = normalize(gradVec + noiseVec * (0.55 + 0.25 * (1.0 - flowEnergy)) + vec2(0.0001, 0.0002));
      vec2 flowTan = vec2(-flowDir.y, flowDir.x);
      float advect = (0.12 + 0.28 * tSpread) * (0.65 + 0.35 * flowEnergy);
      float swirl = (spreadNoise2 - 0.5) * (0.10 + 0.16 * tSpread);

      vec2 metricDirX = normalize(vec2(1.0 / max(metricScale.x, 0.0001), 0.0));
      vec2 metricDirY = normalize(vec2(0.0, 1.0 / max(metricScale.y, 0.0001)));
      vec2 metricDiag1 = normalize(metricDirX + metricDirY);
      vec2 metricDiag2 = normalize(metricDirX - metricDirY);
      vec2 dirX = normalize(metricDirX + flowDir * advect + flowTan * swirl + vec2(0.0001));
      vec2 dirY = normalize(metricDirY + flowDir * (advect * 0.82) - flowTan * (swirl * 0.9) + vec2(0.0001));
      vec2 dirD1 = normalize(metricDiag1 + flowDir * (advect * 0.7) + flowTan * (swirl * 0.6) + vec2(0.0001));
      vec2 dirD2 = normalize(metricDiag2 + flowDir * (advect * 0.7) - flowTan * (swirl * 0.6) + vec2(0.0001));

      vec2 rX = dirX * radius;
      vec2 rY = dirY * radius;
      vec2 rD1 = dirD1 * radius;
      vec2 rD2 = dirD2 * radius;
      vec2 rXm = dirX * prevRadius;
      vec2 rYm = dirY * prevRadius;
      vec2 rD1m = dirD1 * prevRadius;
      vec2 rD2m = dirD2 * prevRadius;

      vec2 uvS;
      vec4 texel;
      float grownMask = seedMask;
      float prevMask = seedMask;
      float sampled = 0.0;

      uvS = clamp(localUv + rX, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv - rX, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv + rY, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv - rY, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv + rD1, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv - rD1, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv + rD2, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);
      uvS = clamp(localUv - rD2, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); grownMask = max(grownMask, sampled);

      uvS = clamp(localUv + rXm, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv - rXm, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv + rYm, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv - rYm, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv + rD1m, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv - rD1m, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv + rD2m, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);
      uvS = clamp(localUv - rD2m, 0.0, 1.0); texel = sampleFlameMask(uvS); sampled = smoothstep(seedThreshold - soft, seedThreshold + soft, max(texel.a, texel.r) * gain); prevMask = max(prevMask, sampled);

      float targetMask = smoothstep(0.001, 0.25, base.a);
      grownMask *= targetMask;
      prevMask *= targetMask;
      float frontier = max(0.0, grownMask - prevMask);

      float settle = smoothstep(0.55, 1.0, tSpread);
      float grownInnerBand = clamp(frontier * (1.2 - settle * 0.35), 0.0, 1.0);
      float grownOuterBand = clamp(grownMask * (1.0 - settle * 0.2), 0.0, 1.0);
      innerBand = mix(directInnerBand, grownInnerBand, phaseBlend);
      outerBand = mix(directOuterBand, grownOuterBand, phaseBlend);
      burnValue = mix(directBurnValue, 1.0 - grownMask, phaseBlend);
      cleanBlend = settle * phaseBlend;
      cleanAlpha = mix(directCleanAlpha, grownMask, phaseBlend);
    }

    vec4 outColor = base;

    vec3 outerEmission = flameColor2.rgb * outerGlowBoost * 2.0;
    vec3 innerEmission = flameColor1.rgb * innerGlowBoost * 5.0;
    vec3 burnColor = mix(outerEmission, innerEmission, clamp(innerBand, 0.0, 1.0));
    vec3 emission = outerEmission * (outerBand * 0.6) + innerEmission * (innerBand * 0.85);
    vec3 baseRgb = base.rgb;
    if (base.a > 0.0001) {
      baseRgb = base.rgb / base.a;
    }
    vec3 mixedRgb = mix(baseRgb, burnColor, outerBand * 0.85);
    mixedRgb += emission * (0.28 + 0.35 * outerBand);
    vec3 finalRgb = mixedRgb;
    float finalAlpha = base.a;
    vec3 rtCore = vec3(1.0);
    vec3 rtOuter = mix(flameColor2.rgb, vec3(1.0), 0.22);
    vec3 rtLayered = vec3(0.0);
    rtLayered += rtOuter * (0.40 + 0.60 * outerBand);
    rtLayered += rtCore * (0.45 * innerBand + 0.30 * rtStyleCore);
    rtLayered += flameColor2.rgb * (0.25 + 0.55 * rtStyleRim) * outerBand;
    vec3 rtFlameTint = clamp(rtLayered, 0.0, 1.0);
    finalRgb = mix(rtFlameTint, baseRgb, rtRelease);
    float maskedAlpha = base.a * clamp(cleanAlpha, 0.0, 1.0);
    finalAlpha = mix(maskedAlpha, base.a, rtRelease);
    float alphaProgress = entranceRtMaskProgress >= 0.0 ? clamp(entranceRtMaskProgress, 0.0, 1.0) : p;
    finalAlpha *= smoothstep(0.015, 0.08, alphaProgress);
    outColor.rgb = finalRgb;
    outColor.a = finalAlpha;

    if (outColor.a <= 0.001) {
      discard;
    }

  gl_FragColor = outColor;
}
